INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('explore_esper_obelisk_search', 3, 0, 'Press M to open your map panel to see where you are right now. Use your map panel and your compass to find the Esper Ringway to Millstone Town portal at 29.8 N, 24.8 W. When you''ve passed through, use the Emerald Obelisk on the other side. Time limit: 24 hours from acceptance.', 'exploration catalog phases', 'hand');
