INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v144', 2, 0, 'You have led the dillos to freedom! The herd has already returned to the Steading. Report your success to Ulafa Olvidan.', 'DAT string table 0x250079de (questimperatorherdrescue.stt) key 0x2e5f1e52; user override: DAT questimperatorherdrescue.stt (0x250079de) ''Herd Rescue'' 2e5f1e52 ''You have led the dillos to freedom! ... Report your success to Ulafa Olvidan.''', 'hand');
