INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v145', 1, 0, 'Speak to Jormun Damuk about the problem at Linvak Tukal.', 'DAT string table 0x250079df (questimperatorlandclaim.stt) key 0x2e5c1e52; user override: DAT questimperatorlandclaim.stt (0x250079df) key 0x2e5c1e52: Speak to Jormun Damuk about the problem at Linvak Tukal.', 'hand');
