INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v145', 3, 0, 'Perhaps there is something left in the ruined records building at 8.7S, 28.4W.', 'DAT string table 0x250079df (questimperatorlandclaim.stt) key 0x2e591e52; user override: DAT 0x250079df key 0x2e591e52: Perhaps there is something left in the ruined records building at 8.7S, 28.4W.', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v145', 4, 0, 'Find a way to reconstitute the ashes.', 'DAT string table 0x250079df (questimperatorlandclaim.stt) key 0x2e5b1e52; user override: DAT 0x250079df key 0x2e5b1e52: Find a way to reconstitute the ashes.', 'hand');
