INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v180', 6, 0, 'Report to Shiela Ondaran.', 'DAT string table 0x25008adb (questara_sandyarmoredillo.stt) key 0xf96df837: phase 6, after the last kill', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v180', 7, 1, 'Shiela Ondaran said: "Welcome to the town of Arwic, adventurer! We''re proud of Arwic, and we need to do everything we can to maintain its glory. We’ve recently discovered that the Sandy Armoredillos are burrowing deep into the hill beneath our city, threatening its very foundations. We''ll need to thin them out to save our town. You’ll be able to find them at the base of our hill to the west."', 'DAT string table 0x25008adb (questara_sandyarmoredillo.stt) key 0x6c459364 (the quest''s summary; Pyrealium shows it for the completed quest)', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v181', 1, 0, '5 Green Phyntos Wasps', 'DAT string table 0x25008add (questarc_greenwasp.stt) key 0x334ef4fd: phase 1 shows the kills left (the DAT''s numbered phase lines count down, as Legions'' QuestGGWNightmare1-6 phases do)', 'hand');
