INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v181', 6, 0, 'Report to Krestovmik.', 'DAT string table 0x25008add (questarc_greenwasp.stt) key 0x33aef4fd: phase 6, after the last kill', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v181', 7, 1, 'Krestovmik said: "Our scouts have reported that the Phyntos Wasps are gathering in the south for their seasonal swarm. We’ve only just managed to weather these onslaughts in the past, but this year the people of Arwic voted to take action before the swarms can wreak any more damage. If you exterminate 5 Green Phyntos Wasps, I''ll reward you."', 'DAT string table 0x25008add (questarc_greenwasp.stt) key 0x6c459364 (the quest''s summary; Pyrealium shows it for the completed quest)', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v183', 1, 0, '5 Carrion Shreth', 'DAT string table 0x25008ade (questard_carrionshreth.stt) key 0xf6ecb2de: phase 1 shows the kills left (the DAT''s numbered phase lines count down, as Legions'' QuestGGWNightmare1-6 phases do)', 'hand');
