INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v184', 11, 0, 'Return to Nola Vontag.', 'DAT string table 0x25008aff (questlind_derangedlasher.stt) key 0x42bf3d9b: phase 11, after the last kill', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v184', 12, 1, 'Nola Vontag said: "Oh dear! My brother Thelos signed up with a mining crew to search for silver on Arramora. They told him it would be safe! But now I’ve heard that he was eaten by a pack of Lashers! I am so small and frail, but even so, I must have my revenge! Rout 10 Deranged Lashers for me, and I will reward you greatly."', 'DAT string table 0x25008aff (questlind_derangedlasher.stt) key 0x6c459364 (the quest''s summary; Pyrealium shows it for the completed quest)', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v186', 1, 0, '10 Vigilant Spawn', 'DAT string table 0x25008b00 (questline_vigilantspawn.stt) key 0x3b25d621: phase 1 shows the kills left (the DAT''s numbered phase lines count down, as Legions'' QuestGGWNightmare1-6 phases do)', 'hand');
