INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v186', 11, 0, 'Report to Audalon.', 'DAT string table 0x25008b00 (questline_vigilantspawn.stt) key 0x3925d621: phase 11, after the last kill', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v186', 12, 1, 'Audalon said:" The Spawn have ever been the direct antipodes of the Naderu, who have celebrated in the ancient songs by my people for as long as they have been sung. The Spawn on Arramora are on the increase, and their very numbers threaten to tip the fragile balance held between them and our beloved Naderu. You must help us preserve this balance, adventurer. Perforate 10 Vigilant Spawn, and I will reward you."', 'DAT string table 0x25008b00 (questline_vigilantspawn.stt) key 0x6c459364 (the quest''s summary; Pyrealium shows it for the completed quest)', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v188', 1, 0, '10 Frost Wisps', 'DAT string table 0x25008b07 (questlini_frostwisp.stt) key 0x0c33ce15: phase 1 shows the kills left (the DAT''s numbered phase lines count down, as Legions'' QuestGGWNightmare1-6 phases do)', 'hand');
