INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v188', 11, 0, 'Return to Tankaru.', 'DAT string table 0x25008b07 (questlini_frostwisp.stt) key 0x0c13ce15: phase 11, after the last kill', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v188', 12, 1, 'Tankaru said: "A dream came to me as I stared into the akiekie fire of my xuta. The mountain heights of Palenqual, known to your people as Arramora, have become unsettled. Frost Wisps have accumulated and bear heavy upon Mother Audetaunga''s winter slopes. I fear an avalanche is nigh, and we must do all we can to prevent it. Destroy 10 Frost Wisps, traveler, and I shall reward you."', 'DAT string table 0x25008b07 (questlini_frostwisp.stt) key 0x6c459364 (the quest''s summary; Pyrealium shows it for the completed quest)', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v193', 1, 0, 'Kill 10 Lumna Niffis.', 'DAT string table 0x250072a5 (questkillniffislumna.stt) key 0x2e5c1e52; user override: DAT questkillniffislumna.stt 0x250072a5 key 2e5c1e52 ''Kill 10 Lumna Niffis.'': the count stage with 10 left (text counts down 10..1)', 'hand');
