INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v208', 11, 0, 'Return to Sister Nell Palnos.', 'DAT string table 0x25008af2 (questike2_faisisclavus.stt) key 0x314fd196: phase 11, after the last kill', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v208', 12, 1, 'Sister Nell Palnos said: "I''ll also need a shipment of silver if I''m to fill my orders of arms and weapons for the Shadow Kingdoms. My mining crews have found just the vein we''ll need in the Tou-Tou Penninsula, but the Faisi Sclavus in that region are proving to be most uncooperative. We''re blocked from completing their mining surveys until the Sclavus threat is removed. Eliminate 10 Faisi Sclavus, and the Brotherhood of Shapers will thank you."', 'DAT string table 0x25008af2 (questike2_faisisclavus.stt) key 0x6c459364 (the quest''s summary; Pyrealium shows it for the completed quest)', 'hand');
