INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v227', 21, 0, 'Report to Brela Shon.', 'DAT string table 0x25008971 (quest_kq4h_toxicgrievver.stt) key 0x34cfc405; user override: DAT 7230 table 0x25008971 (Exterminate the Toxic Grievvers[E]) key 0x34cfc405: ''Report to Brela Shon.''', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v227', 22, 1, 'Brela Shon said: \qThe Grievvers of this region are vicious beasts and must be exterminated if our colonizing efforts are to be a success. The Knorr Expeditionary Forces has authorized me to enlist the aid of strong adventurers to eradicate this threat to our people. Should you kill twenty Toxic Grievvers, report back to me and I shall reward you.\q', 'DAT string table 0x25008971 (quest_kq4h_toxicgrievver.stt) key 0x6c459364; user override: DAT 7230 table 0x25008971 key 0x6c459364 (the quest summary: Brela Shon''s offer text), the completed line the DAT hunts'' generator uses (quests 184, 197, 234)', 'hand');
