INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v228', 21, 0, 'Report to Sia Jorlorn.', 'DAT string table 0x2500896f (quest_kq4f_anguishfelsister.stt) key 0x96af090a: phase 21, after the last kill', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v228', 22, 1, 'Sia Jorlorn said: "We''ve heard reports that the Felsisters continue in their plots with the Thralls against us. We must persevere in our efforts to stabilize the continent for future generations. Kill twenty Anguish Felsisters, and I shall reward you."', 'DAT string table 0x2500896f (quest_kq4f_anguishfelsister.stt) key 0x6c459364 (the quest''s summary; Pyrealium shows it for the completed quest)', 'hand');
