INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v234', 21, 0, 'Report to Jasper Urleg.', 'DAT string table 0x2500896a (quest_kq4a_sandstonecolossus.stt) key 0x82d5222b: phase 21, after the last kill', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v234', 22, 1, 'Jasper Urleg said: "We''ve learned that in the times since the early Lugian settlers of Knorr withdrew to the safety of the shelters, their mighty Collossus have run wild. Once used by their mortal masters to tame the wilderness of this continent, they now run unchecked and are a threat to us all now. You must help us get them back under control. Unfortunately, this means they must be destroyed."', 'DAT string table 0x2500896a (quest_kq4a_sandstonecolossus.stt) key 0x6c459364 (the quest''s summary; Pyrealium shows it for the completed quest)', 'hand');
