INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v276', 1, 0, 'Find and destroy the Chromast Sclavus.', 'DAT string table 0x250089d2 (quest_bm3d_templechromast.stt) key 0x2e5c1e52; user override: DAT quest_bm3d_templechromast.stt (0x250089d2) key 0x2e5c1e52: ''Find and destroy the Chromast Sclavus.''', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v276', 2, 0, 'Return to Elion Magnaron.', 'DAT string table 0x250089d2 (quest_bm3d_templechromast.stt) key 0x2e5f1e52; user override: DAT quest_bm3d_templechromast.stt (0x250089d2) key 0x2e5f1e52: ''Return to Elion Magnaron.''', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v276', 3, 1, 'Elion Magnaron said: \qA temple of great interest to the Knorr Expeditionary Scholars lies to the south. We scouts were dispatched to survey the area for potential threats, and we found what we were looking for. A band of Chromu Sclavus have taken up residence in the temple and will allow no one near it. We believe that if their leader, the Chromast Chromu, is killed, then the rest will disband in terror. Now all we need is a brave adventurer with a strong arm to aid us in this task. Can we depend on you?\q', 'DAT string table 0x250089d2 (quest_bm3d_templechromast.stt) key 0x6c459364; user override: DAT quest_bm3d_templechromast.stt (0x250089d2) key 0x6c459364 (the quest summary), the completed line the DAT hunts'' generator uses (quests 184, 197, 234)', 'hand');
