INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v283', 22, 1, 'Onakhe said: "The early Tumerok settlers of this lands abandoned their Takeru when they withdrew to the shelters before the Devastation. In the ages since, the Takeru have forgotten us. We have returned, but the Takeru no longer answer to our call. Instead, they attack all who approach them. It is with great sadness that I must ask you to help us to destroy them, before they can cause greater harm to our people."', 'DAT string table 0x25008970 (quest_kq4g_cahitakeru.stt) key 0x6c459364 (the quest''s summary; Pyrealium shows it for the completed quest)', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v39', 1, 0, 'Kill 1 Degenerate Mucor Sporesower: 1 left.', 'Pyrealium journal text (no retail line is recovered for this step); steps per AC2 Vault quests/db id 39', 'hand');
