INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('talk_470040a7', 1, 'Say', 0, 'Siege Stores. Begins with: Torgara (30.5S, 34.2E). Starting area: Center of Skyport , Knorr Wilds. Requirements: Level 30+. Time allowed: 10 hours. Repeat interval: 6 days. Listed experience reward: 25% (Cap: 12,518,366 @ L45). Listed rewards: 30,000 XP for each extra bread. Information only; no task has been started.', 'Torgara', '', '', '', 'https://20oz.net/index.php/Siege_Stores.html', 'npc');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('talk_470040ea_1', 1, 'Say', 0, 'Journey to Fort Strathelar. After the Aerie assignments, Otonku needs a report carried to Legionary Brigadier Maekarn at Fort Strathelar. Begins with: Elite Legionary Otonku (38.7S, 45.4E). Starting area: The Aerie in Knorr Ramparts. Requirements: need all The Aerie Slays and Exterminate quests completed. Intended Level : 70. Time allowed: 6 days 23hours. Repeat interval: 6 days 23hours. Information only; no task has been started.', 'Elite Legionary Otonku', '', '', '', 'https://20oz.net/index.php/Journey_to_Fort_Strathelar.html', 'npc');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('talk_470040ea_2', 1, 'Say', 0, 'Journey to Fort Strathelar. Listed experience reward: 1% XP. Information only; no task has been started.', 'Elite Legionary Otonku', '', '', '', 'https://20oz.net/index.php/Journey_to_Fort_Strathelar.html', 'npc');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('talk_470040f1_1', 1, 'Say', 0, 'Journey to Greenstone. After the Foundry Expeditionary Forces assignments, Dell sends a knapsack to Captain Trammel in Greenstone. Begins with: Leftenant Dell (32.8S, 52.3E) in Jethric''s Outpost. Starting area: Greenstone. Requirements: Level 50+, must have completed all Foundry Expeditionary Forces Quests. Time allowed: 7 days. Repeat interval: 7 days. Information only; no task has been started.', 'Leftenant Dell', '', '', '', 'https://20oz.net/index.php/Journey_to_Greenstone.html', 'npc');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('talk_470040f1_2', 1, 'Say', 0, 'Journey to Greenstone. Listed experience reward: 1% XP, cap: 2,503,673 @ Lv50. Listed rewards: Lore about Greenstone. Information only; no task has been started.', 'Leftenant Dell', '', '', '', 'https://20oz.net/index.php/Journey_to_Greenstone.html', 'npc');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('talk_470040f4', 1, 'Say', 0, 'Journey to the Aerie. Begins with: Captain Trammel. Starting area: Greenstone. Requirements: Level 60+, must have completed all six Gardens kill tasks. Time allowed: 7 days. Repeat interval: None. Listed experience reward: 1% XP, 47,624,866 @ 60. Information only; no task has been started.', 'Captain Trammel', '', '', '', 'https://20oz.net/index.php/Journey_to_the_Aerie.html', 'npc');
