INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('v103_s1_ok', 1, 'TakeItem', 0, '0x4700234b', '1', '', '', '', 'AC2 Vault quests/db id 103: hand 1 Lupe Letter to Kiral', 'hand');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('v103_s1_ok', 2, 'Tell', 0, '0x250017ea', '0x668008ab', '', '', '', 'DAT string table 0x250017ea key 0x668008ab; user override: DAT tumerokshrethwardenquest.stt (250017ea) key 668008ab: Kiral on the letter, ''Hmm... this is disturbing. Lupe''s hunting must have angered the Ero-Bals ... While carrying this talisman, release three Ero-Bals''', 'hand');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('v103_s1_ok', 3, 'GiveItem', 0, '0x47002337', '1', '', '', '', 'user override: DAT wsl_talismanwoodentiny.entity (talismanwoodentiny.stt 25007600 ''Tiny Wooden Talisman[E]''); AC2 Vault quests/db id 103: the player receives Tiny Wooden Talisman', 'hand');
