INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('v103_s3_ok', 1, 'TakeItem', 0, '0x47002337', '1', '', '', '', 'AC2 Vault quests/db id 103: hand 1 Tiny Wooden Talisman to Kiral', 'hand');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('v103_s3_ok', 2, 'Tell', 0, '0x250017ea', '0xee19ab23', '', '', '', 'DAT string table 0x250017ea key 0xee19ab23; user override: DAT tumerokshrethwardenquest.stt (250017ea) key ee19ab23: emote ''Kiral closes her eyes and mutters a few words as she turns the Tiny Wooden Talisman over and over in her hands.''', 'hand');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('v103_s3_ok', 3, 'Tell', 0, '0x250017ea', '0xee19b323', '', '', '', 'DAT string table 0x250017ea key 0xee19b323; user override: DAT tumerokshrethwardenquest.stt (250017ea) key ee19b323: ''Ah, excellent. I sense much rage and hatred in this talisman. But if we calm the spirits thus...''', 'hand');
INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('v103_s3_ok', 4, 'Tell', 0, '0x250017ea', '0xee19a323', '', '', '', 'DAT string table 0x250017ea key 0xee19a323; user override: DAT tumerokshrethwardenquest.stt (250017ea) key ee19a323: ''The talisman has been blessed with release. Tell Lupe to wear this around her neck ...''', 'hand');
