INSERT INTO emote_action (emote_set, ord, action, delay_ms, p1, p2, p3, p4, p5, source, family) VALUES ('v103_start', 1, 'Tell', 0, '0x250074b1', '0x83889cdb', '', '', '', 'DAT string table 0x250074b1 key 0x83889cdb; user override: DAT lupe.stt (250074b1) key 83889cdb: ''I have been disturbed by terrible dreams of late ... Please take this letter to the scholar Kiral in Rakani.''', 'hand');
